$('exam-paper-preview-tab').addEventListener('change',e=>{if(e.target.matches('[data-blueprint-question]'))updateBlueprintSelection();});
$('exam-paper-preview-tab').addEventListener('click',async e=>{const button=e.target.closest('[data-replace-blueprint-question]');if(!button)return;button.disabled=true;try{const item=button.closest('[data-blueprint-item]');const excluded=[...document.querySelectorAll('[data-blueprint-item]')].map(x=>Number(x.dataset.blueprintItem));const q=await api('/api/admin/exam-blueprints/replacement',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({blueprint:readBlueprint(),rule_id:item.dataset.ruleId,exclude_question_ids:excluded})});item.dataset.blueprintItem=q.id;item.querySelector('[data-blueprint-question]').dataset.blueprintQuestion=q.id;item.querySelector('label').lastChild.textContent=`Include question #${q.id}`;button.dataset.replaceBlueprintQuestion=q.id;item.querySelector('.exam-paper-meta').innerHTML=`<span>${esc(q.chapter||'No chapter')}</span><span>${esc(q.topic||'Any topic')}</span><span>${esc(q.difficulty)}</span><span>${esc(q.qtype)}</span><span>${esc(q.source_type)}</span><span>${esc(q.verification_status)}</span><span>Used ${q.usage_count} times</span>`;renderInto(item.querySelector('.rendered'),q.statement);notify('Question replaced within the same blueprint rule.');}catch(err){notify(err.message);}finally{button.disabled=false;}});
async function approveBlueprint(status,button){button.disabled=true;try{const selected=[...document.querySelectorAll('[data-blueprint-question]:checked')];const question_ids=selected.map(x=>Number(x.dataset.blueprintQuestion));const selection_rule_ids=Object.fromEntries(selected.map(x=>[x.dataset.blueprintQuestion,x.closest('[data-rule-id]').dataset.ruleId]));if(question_ids.length!==readBlueprint().total_questions)throw new Error('Select exactly the requested number of questions.');const result=await api('/api/admin/exam-blueprints/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({blueprint:readBlueprint(),question_ids,selection_rule_ids,status})});notify(`Durable exam #${result.id} created.`);showView('admin-exams');}catch(err){notify(err.message);}finally{button.disabled=false;}}
