function setWorkspace(mode){document.querySelectorAll('#analytics-limit,#analytics-days,#analytics-subject,#analytics-difficulty,#analytics-qtype').forEach(el=>el.parentElement.hidden=signedInUser?.role!=='STUDENT');document.querySelector('#student-analytics-panel [data-mentor]').hidden=signedInUser?.role!=='STUDENT';const admin=signedInUser?.role==='ADMIN';const studentMode=admin&&mode==='student';$('admin-nav').hidden=!admin||studentMode;$('student-nav').hidden=!(signedInUser?.role==='STUDENT'||studentMode);$('proctor-nav').hidden=signedInUser?.role!=='PROCTOR';$('workspace-switch').hidden=!admin;$('workspace-switch').textContent=studentMode?'Switch to admin workspace':'Switch to student view';$('workspace-switch').dataset.mode=studentMode?'student':'admin';$('account-role').textContent=studentMode?'ADMIN · Student view':signedInUser?.role||'';const fallback=signedInUser?.role==='PROCTOR'?'admin-exams':'dashboard',requested=new URL(location.href).searchParams.get('view');const allowed=requested&&$(requested+'-panel')&&[...document.querySelectorAll('.sidebar nav:not([hidden]) [data-view]')].some(node=>node.dataset.view===requested);showView(allowed?requested:fallback,{history:'replace'});}
async function finishLogin(user){if(user.mfa_required){location.assign('/static/mfa.html');return;}signedInUser=user;window.hidePublicSite?.();$('login-screen').hidden=true;$('app-header').hidden=false;$('app-shell').hidden=false;$('account-name').textContent=user.display_name||user.email;$('account-email').textContent=user.email;$('account-avatar').src=user.profile_picture||'/static/app-icon.svg';$('account-avatar').onerror=()=>{$('account-avatar').onerror=null;$('account-avatar').src='/static/app-icon.svg';};setWorkspace('admin');window.dispatchEvent(new CustomEvent('mobile:login',{detail:user}));const pending=sessionStorage.getItem('meritiqra_pending_exam');if(pending&&user.role==='STUDENT'){sessionStorage.removeItem('meritiqra_pending_exam');try{await api(`/api/exams/${Number(pending)}/enroll`,{method:'POST'});notify('Registration complete. Available Exams now shows Enter proctor and Start exam.');showView('available-exams');}catch(error){notify(error.message);showView('available-exams');}}}
function renderGoogleSignIn(clientId,container,onUser,onError){container.textContent='Loading secure Google sign-in…';const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>{container.textContent='';google.accounts.id.initialize({client_id:clientId,callback:async r=>{try{await onUser(await api('/api/auth/google',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({credential:r.credential,login_role:container.id==='google-signin'?($('login-role')?.value||'STUDENT'):'STUDENT'})}));}catch(e){onError(e);}}});google.accounts.id.renderButton(container,{theme:'outline',size:'large',width:280,text:'continue_with'});};script.onerror=()=>{container.textContent='';onError(new Error('Google sign-in could not load. Check browser content blocking and reload this page.'));};document.head.append(script);}
async function bootstrapAuth(){try{return finishLogin(await api('/api/auth/me'));}catch{}const config=await fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json());if(window.MeritIQraNative){$('login-screen').hidden=false;$('app-shell').hidden=true;$('login-title').textContent='Continue with Gmail';$('google-signin').hidden=false;return;}window.showPublicSite?.();$('login-screen').hidden=false;$('bootstrap-admin-toggle').hidden=true;$('admin-login-toggle').hidden=true;$('admin-login-toggle').disabled=!config.local_admin;$('admin-login-email').value='';if(config.client_id){renderGoogleSignIn(config.client_id,$('google-signin'),finishLogin,e=>{$('login-message').textContent=e.message;});}else if(config.mock){$('mock-signin').hidden=false;}else $('login-message').textContent='Students and learners continue with Gmail. Administrator access is available from Admin Login.';}
