async function bootstrapPublicRegistration(){
  const match=location.pathname.match(/^\/register\/exam\/([^/]+)$/);if(!match)return false;
  const token=match[1];window.hidePublicSite?.();$('public-registration').hidden=false;
  try{
    const exam=await fetch(`/api/register/exam/${token}`,{cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.detail);return d;});
    $('public-exam-name').textContent=exam.name;$('public-exam-summary').textContent=`${exam.subject||'Examination'} · ${exam.duration_minutes} minutes`;
    if(window.setupSharedGoogleEnrollment&&await window.setupSharedGoogleEnrollment(token,exam))return true;
    $('public-fallback-toggle').textContent='Option 2 · Login without Gmail';$('public-new-registration').textContent='Register without Gmail';$('public-continue-login').textContent='Login without Gmail';
    const showRegistration=()=>{$('public-registration-form').hidden=false;$('public-student-login-form').hidden=true;$('public-new-registration').classList.add('primary');$('public-continue-login').classList.remove('primary');$('public-registration-message').textContent='';};
    const showStudentLogin=()=>{$('public-registration-form').hidden=true;$('public-student-login-form').hidden=false;$('public-new-registration').classList.remove('primary');$('public-continue-login').classList.add('primary');$('public-student-login-form').elements.email.focus();};
    $('public-new-registration').onclick=showRegistration;$('public-continue-login').onclick=showStudentLogin;
    const config=await fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json()).catch(()=>({}));
    if(config.client_id&&!window.MeritIQraNative){
      $('public-google-block').hidden=false;$('public-fallback').hidden=true;
      $('public-fallback-toggle').onclick=()=>{$('public-fallback').hidden=false;$('public-fallback-toggle').hidden=true;showRegistration();};
      renderGoogleSignIn(config.client_id,$('public-google-signin'),async user=>{history.replaceState({},'','/app');$('public-registration').hidden=true;await finishLogin(user);showView('my-exams');},err=>{$('public-registration-message').textContent=err.message;});
    }
    $('public-registration-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{const r=await fetch(`/api/register/exam/${token}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.detail);$('public-registration-message').textContent=d.message;const login=$('public-student-login-form');login.elements.email.value=body.email;login.elements.date_of_birth.value=body.date_of_birth;login.elements.phone_number.value=body.phone_number;showStudentLogin();$('public-registration-message').textContent=d.message;}catch(err){$('public-registration-message').textContent=err.message;}};
    $('public-student-login-form').onsubmit=async e=>{e.preventDefault();$('public-registration-message').textContent='Signing in…';try{const user=await api('/api/auth/student-registration-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const enrolled=await api(`/api/register/exam/${encodeURIComponent(token)}/enroll`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});history.replaceState({},'','/app');$('public-registration').hidden=true;await finishLogin(user);if(exam.proctor_required){showView('available-exams');await loadAvailableExams();notify('You are enrolled. Enter the proctor code to start this exam.');}else{const session=await api(`/api/exams/${enrolled.exam_id||exam.id}/sessions`,{method:'POST'});await openSecureExam(session.session_id);notify('Your exam is ready.');}}catch(err){$('public-registration-message').textContent=err.message;}};
  }catch(err){$('public-exam-summary').textContent=err.message;$('public-registration-form').hidden=true;}
  return true;
}
bootstrapPublicRegistration().then(active=>{if(!active)bootstrapAuth();});
window.addEventListener('popstate',()=>{if(!signedInUser||secureExamActive)return;const requested=new URL(location.href).searchParams.get('view')||'dashboard';if($(requested+'-panel'))showView(requested,{history:'none'});});

// Secure exam browser controls. Client controls deter casual misuse while
// server audit events provide an enforceable violation trail.
document.addEventListener('copy',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('COPY_ATTEMPT');}});
document.addEventListener('cut',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('CUT_ATTEMPT');}});
document.addEventListener('paste',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('PASTE_ATTEMPT');}});
document.addEventListener('contextmenu',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('CONTEXT_MENU');}});
document.addEventListener('keydown',event=>{if(!secureExamActive)return;const key=event.key.toLowerCase();if(event.key==='F12'||(event.ctrlKey||event.metaKey)&&['c','x','v','p','s','u','t','n','w'].includes(key)||event.ctrlKey&&event.shiftKey&&['i','j','c'].includes(key)){event.preventDefault();recordSecurityViolation((key==='p')?'PRINT_ATTEMPT':(['t','n','w'].includes(key)?'TAB_SWITCH':'DEVTOOLS_SHORTCUT'));}});
document.addEventListener('visibilitychange',()=>{if(!window.MeritIQraNative&&secureExamActive&&document.hidden)recordSecurityViolation('TAB_SWITCH');});
window.addEventListener('blur',()=>{if(!window.MeritIQraNative&&secureExamActive)recordSecurityViolation('WINDOW_BLUR');});
document.addEventListener('fullscreenchange',()=>{if(secureExamActive&&document.body.dataset.examDisplay==='fullscreen'&&!document.fullscreenElement)recordSecurityViolation('FULLSCREEN_EXIT');});
window.addEventListener('beforeunload',event=>{if(!secureExamActive)return;recordSecurityViolation('NAVIGATION_ATTEMPT');event.preventDefault();event.returnValue='Your examination is still in progress.';});
$('exam-home')?.addEventListener('click',event=>{if(!secureExamActive)return;if(!confirm('Your exam is still in progress. Leave secure exam mode and return home? The active attempt will remain timed.'))event.preventDefault();else recordSecurityViolation('NAVIGATION_ATTEMPT');});
